import os, base64, gzip, sqlite3

# Self-contained SQLite injector for D_BO_000000481 (02, 03, 05, 06, 07)
DATA = {
    '02': '',
    '03': '',
    '05': '',
    '06': '',
    '07': '',
}

base_dir = 'models/conversion/C_BO_000000481'
os.makedirs(base_dir, exist_ok=True)

for code, b64 in DATA.items():
    file_path = os.path.join(base_dir, f'D_BO_000000481_{code}.sqlite')
    raw_data = gzip.decompress(base64.b64decode(b64))
    with open(file_path, 'wb') as f:
        f.write(raw_data)
    conn = sqlite3.connect(file_path)
    tables = [t[0] for t in conn.cursor().execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()]
    print(f"✅ D_BO_000000481_{code}.sqlite creado con éxito. Tablas: {tables}")
    conn.close()

print("\n=== TODOS LOS ARCHIVOS SQLITE HAN SIDO CREADOS CON EXITO ===")
